WITH gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY status ORDER BY paid_at, id) + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM payments), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY status ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT CASE WHEN amount >= 1580 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, COUNT_IF(method = 'paypal') AS paypal_events, COUNT(DISTINCT order_id) AS distinct_order_ids, MAX(paid_at) AS ended_at, SIZE(COLLECT_SET(status)) AS num_status, MIN(paid_at) AS first_paid_at FROM islands GROUP BY amount_tier ORDER BY num_status NULLS LAST
